// Produce one output item per bureau that has disputable items.
const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const byBureau = {};
for (const r of rows) (byBureau[r.bureau] = byBureau[r.bureau] || []).push(r);
return Object.entries(byBureau).map(([bureau, items]) => ({ json: {
  case_id: items[0].case_id, bureau, round: items[0].round,
  consumer: { first_name: items[0].first_name,
    last_name: items[0].last_name, street: items[0].street,
    city: items[0].city, state: items[0].state,
    zip: items[0].zip, ssn_last4: items[0].ssn_last4 },
  items } }));

// Build the Anthropic request to draft one bureau letter.
const d = $input.first().json;
const roundGuide = {
  1: 'Round 1: a clear factual dispute under 15 U.S.C. 1681i. State'
   + ' each inaccuracy and request reinvestigation and correction or'
   + ' deletion within 30 days.',
  2: 'Round 2: a Method of Verification request under 1681i(a)(7).'
   + ' Ask how each item was verified — describe the procedure, the'
   + ' business contacted, and the records relied on.',
  3: 'Round 3: procedural / furnisher escalation citing 1681s-2(b)'
   + ' and the reasonable-reinvestigation standard. Request deletion'
   + ' where verification was inadequate.'
};
const system = [
  'You draft FCRA dispute letters for a licensed credit-repair',
  'service. Rules: (1) Only assert facts supported by the supplied',
  'item data and dispute basis. (2) Never instruct anyone to make a',
  'false statement. (3) No guarantees about outcomes or score',
  'changes. (4) Plain, firm, professional tone. (5) Cite statute by',
  'section. Output ONLY the letter body text.'
].join(' ');
const user = [
  roundGuide[d.round] || roundGuide[1], '',
  'Bureau: ' + d.bureau,
  'Consumer: ' + JSON.stringify(d.consumer),
  'Items to dispute: ' + JSON.stringify(d.items, null, 2)
].join('\n');
return [{ json: { ...d, anthropic_request: {
  model: 'claude-sonnet-4-6', max_tokens: 2048,
  system, messages: [{ role: 'user', content: user }] } } }];

// Lint the draft against CROA / FCRA content rules.
const resp = $input.first().json;
const d = $('Build Letter Prompt').first().json;
const body = (resp.content && resp.content[0] && resp.content[0].text) || '';
const banned = [/guarantee/i, /guaranteed/i, /erase your debt/i,
  /new credit identity/i, /CPN/i, /will raise your score/i];
const violations = banned.filter(rx => rx.test(body)).map(String);
const hasStatute = /1681/.test(body);
const passed = violations.length === 0 && hasStatute && body.length > 200;
return [{ json: { case_id: d.case_id, bureau: d.bureau,
  round: d.round, letter_body: body,
  item_ids: d.items.map(i => i.item_id),
  lint_passed: passed, lint_violations: violations,
  letter_status: passed ? 'pending_review' : 'needs_rewrite' } }];
